/** 判题脚手架：第三方响应层抛出的错误类型与重试层契约（考生与测试共用）。 */
export class HttpError extends Error {
  readonly status: number;
  readonly retryAfterMs: number | null;

  constructor(status: number, retryAfterMs?: number, message = 'http error') {
    super(message);
    this.name = 'HttpError';
    this.status = status;
    this.retryAfterMs = retryAfterMs ?? null;
  }
}

export type FailureKind = 'http' | 'network' | 'contract' | 'aborted';

export interface RetryOptions {
  /** 调用方的取消信号；必须原样透传给 request（用例断言 signal 身份） */
  signal?: AbortSignal;
  method?: 'GET' | 'HEAD' | 'POST' | 'PUT' | 'PATCH' | 'DELETE';
  idempotencyKey?: string;
  maxAttempts?: number;
  baseMs?: number;
  maxDelayMs?: number;
  budgetMs?: number;
  random?: () => number;
  sleep?: (ms: number, signal: AbortSignal) => Promise<void>;
}

export type Outcome<T> =
  | { ok: true; data: T; attempts: number }
  | { ok: false; kind: FailureKind; error: unknown; attempts: number };

import { expect, it } from 'vitest';
import { HttpError } from './http';
import { fetchWithRetry } from './Solution';

interface Attempt {
  signal: AbortSignal;
  attempt: number;
}

/** 记录型 sleep：把"等了多久"变成可断言的数据，避免用墙钟计时判分（jsdom 下必然 flaky）。 */
function harness(opts: { failures: unknown[]; random?: () => number }) {
  const sleeps: number[] = [];
  const attempts: Attempt[] = [];
  let cursor = 0;
  const request = async (signal: AbortSignal, attempt: number) => {
    attempts.push({ signal, attempt });
    const next = opts.failures[cursor];
    cursor += 1;
    if (next === undefined) return 'data-' + attempt;
    throw next;
  };
  const sleep = async (ms: number) => {
    sleeps.push(ms);
  };
  return { sleeps, attempts, request, sleep, random: opts.random ?? (() => 0.5) };
}

const DEFAULTS = { baseMs: 100, maxDelayMs: 2000, maxAttempts: 3 };

it('单次成功不重试也不等待', async () => {
  const h = harness({ failures: [] });
  const out = await fetchWithRetry(h.request, { ...DEFAULTS, random: h.random, sleep: h.sleep });
  expect(JSON.stringify(out)).toBe('{"ok":true,"data":"data-1","attempts":1}');
  expect(h.sleeps).toEqual([]);
  expect(h.attempts.length).toBe(1);
});

it('503 两次后成功且退避随注入的 random 变化', async () => {
  const a = harness({ failures: [new HttpError(503), new HttpError(503)], random: () => 0.5 });
  const outA = await fetchWithRetry(a.request, { ...DEFAULTS, random: a.random, sleep: a.sleep });
  expect(outA.ok).toBe(true);
  expect(outA.attempts).toBe(3);
  expect(a.sleeps).toEqual([100, 200]);

  const b = harness({ failures: [new HttpError(503), new HttpError(503)], random: () => 0 });
  const outB = await fetchWithRetry(b.request, { ...DEFAULTS, random: b.random, sleep: b.sleep });
  expect(outB.attempts).toBe(3);
  expect(b.sleeps).toEqual([50, 100]);
});

it('429 的 Retry-After 优先于计算出的退避', async () => {
  const h = harness({ failures: [new HttpError(429, 5000)] });
  const out = await fetchWithRetry(h.request, { ...DEFAULTS, random: h.random, sleep: h.sleep });
  expect(out.ok).toBe(true);
  expect(h.sleeps).toEqual([5000]);
  expect(out.attempts).toBe(2);
});

it('重复点击的非幂等 POST 首次失败即返回不重试', async () => {
  const h = harness({ failures: [new HttpError(503), new HttpError(503), new HttpError(503)] });
  const out = await fetchWithRetry(h.request, { ...DEFAULTS, method: 'POST', random: h.random, sleep: h.sleep });
  expect(out.ok).toBe(false);
  expect(out.kind).toBe('http');
  expect(out.attempts).toBe(1);
  expect(h.sleeps).toEqual([]);
});

it('契约错误 400 不重试且分类为 contract', async () => {
  const h = harness({ failures: [new HttpError(400)] });
  const out = await fetchWithRetry(h.request, { ...DEFAULTS, method: 'GET', random: h.random, sleep: h.sleep });
  expect(out.kind).toBe('contract');
  expect(out.attempts).toBe(1);
  expect(h.sleeps).toEqual([]);
});

it('外部 signal 取消后停止重试并原样透传同一 signal', async () => {
  const controller = new AbortController();
  const h = harness({ failures: [new HttpError(503), new HttpError(503)] });
  const out = await fetchWithRetry(h.request, {
    ...DEFAULTS,
    signal: controller.signal,
    random: h.random,
    sleep: async (ms: number, signal: AbortSignal) => {
      h.sleeps.push(ms);
      controller.abort();
    },
  });
  expect(out.kind).toBe('aborted');
  expect(out.attempts).toBe(1);
  expect(h.attempts[0].signal).toBe(controller.signal);
});

it('预算耗尽按 aborted 分类且不再排下一次等待', async () => {
  const h = harness({ failures: [new HttpError(503), new HttpError(503), new HttpError(503)] });
  const out = await fetchWithRetry(h.request, {
    baseMs: 200,
    maxDelayMs: 2000,
    maxAttempts: 5,
    budgetMs: 250,
    random: h.random,
    sleep: h.sleep,
  });
  expect(out.kind).toBe('aborted');
  expect(out.attempts).toBe(2);
  expect(h.sleeps).toEqual([200]);
});

