import { HttpError } from './http';
import type { Outcome, RetryOptions } from './http';

const IDEMPOTENT = new Set(['GET', 'HEAD']);

function asHttpError(error: unknown): HttpError | null {
  return error instanceof HttpError ? error : null;
}

/** 4xx（除 429）是契约破坏：重试只会放大故障。 */
function isRetryable(error: unknown): boolean {
  const http = asHttpError(error);
  if (!http) return true;
  if (http.status === 429) return true;
  return http.status >= 500;
}

function defaultSleep(ms: number, signal: AbortSignal): Promise<void> {
  return new Promise((resolve) => {
    const id = setTimeout(() => {
      signal.removeEventListener('abort', onAbort);
      resolve();
    }, ms);
    function onAbort() {
      clearTimeout(id);
      resolve();
    }
    signal.addEventListener('abort', onAbort, { once: true });
  });
}

export async function fetchWithRetry<T>(
  request: (signal: AbortSignal, attempt: number) => Promise<T>,
  opts: RetryOptions = {},
): Promise<Outcome<T>> {
  const {
    signal,
    method = 'GET',
    idempotencyKey,
    maxAttempts = 3,
    baseMs = 100,
    maxDelayMs = 2000,
    budgetMs = Number.POSITIVE_INFINITY,
    random = Math.random,
    sleep = defaultSleep,
  } = opts;

  const controller = new AbortController();
  if (signal) {
    if (signal.aborted) controller.abort();
    else signal.addEventListener('abort', () => controller.abort(), { once: true });
  }
  /** 调用方给了 signal 就用它的同一个实例（用例断言 identity），否则用内部 controller。 */
  const used: AbortSignal = signal ?? controller.signal;
  const canRetry = IDEMPOTENT.has(method) || typeof idempotencyKey === 'string' && idempotencyKey.length > 0;

  let spent = 0;
  let lastError: unknown = undefined;
  let attempts = 0;

  for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {
    if (used.aborted) {
      return { ok: false, kind: 'aborted', error: lastError, attempts };
    }
    attempts = attempt;
    try {
      const data = await request(used, attempt);
      return { ok: true, data, attempts };
    } catch (error) {
      lastError = error;
      const http = asHttpError(error);
      if (http && http.status >= 400 && http.status < 500 && http.status !== 429) {
        return { ok: false, kind: 'contract', error, attempts };
      }
      if (!isRetryable(error) || !canRetry || attempt === maxAttempts) {
        return { ok: false, kind: http ? 'http' : 'network', error, attempts };
      }

      const raw = Math.min(maxDelayMs, baseMs * 2 ** (attempt - 1));
      const jittered = Math.round(raw * (0.5 + random()));
      const retryAfter = http && http.status === 429 ? http.retryAfterMs : null;
      const delay = retryAfter === null || retryAfter === undefined ? jittered : Math.max(jittered, retryAfter);

      if (spent + delay > budgetMs) {
        return { ok: false, kind: 'aborted', error, attempts };
      }
      spent += delay;
      await sleep(delay, used);
      if (used.aborted) {
        return { ok: false, kind: 'aborted', error, attempts };
      }
    }
  }
  return { ok: false, kind: 'network', error: lastError, attempts };
}

