import { HttpError } from './http';
import type { Outcome, RetryOptions } from './http';

/** 朴素实现：固定线性退避、无抖动、什么都敢重试、不看取消信号。 */
export async function fetchWithRetry<T>(
  request: (signal: AbortSignal, attempt: number) => Promise<T>,
  opts: RetryOptions = {},
): Promise<Outcome<T>> {
  const { signal, maxAttempts = 3, baseMs = 100, sleep } = opts;
  let lastError: unknown = undefined;
  for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {
    try {
      const data = await request(signal ?? new AbortController().signal, attempt);
      return { ok: true, data, attempts: attempt };
    } catch (error) {
      lastError = error;
      if (attempt === maxAttempts) break;
      const ms = baseMs * attempt;
      if (sleep) await sleep(ms, signal ?? new AbortController().signal);
    }
  }
  const http = lastError instanceof HttpError ? lastError : null;
  return { ok: false, kind: http ? 'http' : 'network', error: lastError, attempts: maxAttempts };
}
